package com.shubham.salarytracker;
import android.content.Context;
import android.util.AtomicFile;
import org.json.*;
import java.io.File;
import java.nio.charset.StandardCharsets;
import java.util.*;
import java.util.regex.*;

final class PaymentDrafts {
 static final Map<String,String> APPS=new LinkedHashMap<>();static{APPS.put("com.google.android.apps.nbu.paisa.user","Google Pay");APPS.put("com.phonepe.app","PhonePe");APPS.put("com.dreamplug.androidapp","CRED");APPS.put("net.one97.paytm","Paytm");}
 static String profile(Context c){String email=DriveSync.current(c);return email.isEmpty()?"device":DriveSync.ns(email);}
 static AtomicFile file(Context c){return new AtomicFile(new File(c.getFilesDir(),"payment-drafts-"+profile(c)+".json"));}
 static synchronized JSONObject read(Context c){try{return new JSONObject(new String(file(c).readFully(),StandardCharsets.UTF_8));}catch(Exception e){try{return new JSONObject().put("drafts",new JSONArray()).put("seen",new JSONArray());}catch(Exception ignored){throw new IllegalStateException();}}}
 static JSONObject parse(String text,long time)throws Exception{String lower=text.toLowerCase(Locale.ROOT);if(lower.matches("(?s).*\\b(otp|pin|password|verification code|failed|declined|pending|request|requested|reminder|due|cashback offer)\\b.*")||!lower.matches("(?s).*\\b(paid|sent|received|debited|credited|successful|successfully)\\b.*"))return null;Matcher m=Pattern.compile("(?:₹|INR\\s*|Rs\\.?\\s*)([0-9][0-9,]*(?:\\.[0-9]{1,2})?)",Pattern.CASE_INSENSITIVE).matcher(text);Set<Long> amounts=new HashSet<>();while(m.find()){try{long n=new java.math.BigDecimal(m.group(1).replace(",","")).movePointRight(2).longValueExact();if(n>0&&n<=10000000000000L)amounts.add(n);}catch(Exception ignored){}}if(amounts.isEmpty())return null;Matcher ref=Pattern.compile("(?:UTR|UPI\\s*(?:ref(?:erence)?|transaction)\\s*(?:no\\.?|id)?|reference\\s*(?:no\\.?|id))\\s*[:#-]?\\s*([A-Za-z0-9]{10,30})",Pattern.CASE_INSENSITIVE).matcher(text);String reference=ref.find()?ref.group(1).toUpperCase(Locale.ROOT):"";return new JSONObject().put("amount",amounts.size()==1?amounts.iterator().next():JSONObject.NULL).put("special",lower.matches("(?s).*credit\\s+card\\s+(?:bill|payment).*" )?"card payment":lower.contains("refund")?"refund":lower.contains("transfer")?"transfer":"").put("income",lower.matches("(?s).*\\b(received|credited)\\b.*")).put("reference",reference).put("text",text.substring(0,Math.min(500,text.length()))).put("time",time);}
 static synchronized void capture(Context c,String pkg,String key,String text,long time)throws Exception{if(!APPS.containsKey(pkg)||!c.getSharedPreferences("payments",0).getBoolean("enabled-"+profile(c),false)||!c.getSharedPreferences("payments",0).getBoolean("app-"+profile(c)+"-"+pkg,false))return;JSONObject draft=parse(text,time);if(draft==null)return;String ref=draft.getString("reference"),id=DriveBackup.hash(ref.isEmpty()?pkg+"|"+key+"|"+time+"|"+text:ref+"|"+draft.opt("amount")+"|"+draft.getBoolean("income"));JSONObject data=read(c);JSONArray seen=data.getJSONArray("seen"),drafts=data.getJSONArray("drafts");for(int i=0;i<seen.length();i++)if(id.equals(seen.getString(i)))return;for(int i=0;i<drafts.length();i++)if(id.equals(drafts.getJSONObject(i).getString("id")))return;if(drafts.length()>=500){c.getSharedPreferences("payments",0).edit().putString("status","Inbox full. Review or dismiss drafts to capture new ones.").apply();return;}draft.put("id",id).put("source",APPS.get(pkg));drafts.put(draft);DriveSync.write(file(c),data.toString());}
 static synchronized void dismiss(Context c,String id)throws Exception{JSONObject data=read(c);JSONArray old=data.getJSONArray("drafts"),next=new JSONArray(),seen=data.getJSONArray("seen");for(int i=0;i<old.length();i++)if(!id.equals(old.getJSONObject(i).getString("id")))next.put(old.get(i));seen.put(id);while(seen.length()>2000)seen.remove(0);data.put("drafts",next);DriveSync.write(file(c),data.toString());}
 static synchronized String settings(Context c)throws Exception{JSONArray apps=new JSONArray();for(Map.Entry<String,String> app:APPS.entrySet())apps.put(new JSONObject().put("id",app.getKey()).put("name",app.getValue()).put("enabled",c.getSharedPreferences("payments",0).getBoolean("app-"+profile(c)+"-"+app.getKey(),false)));return new JSONObject().put("enabled",c.getSharedPreferences("payments",0).getBoolean("enabled-"+profile(c),false)).put("apps",apps).put("status",c.getSharedPreferences("payments",0).getString("status","")).toString();}
}
